procedure BowlingWinBack {
  about "Nudge bowlers whose league night was long ago"
  policy BowlingPolicy
  sheet Leagues "Leagues" { bowler: Text, phone: Phone, next_game: DateTime, status: Text, dues: Money, shoe_size_notes: Text private }
  trigger every thursday at 08:30

  let all = fetch Leagues
  let old = filter all where days_between(next_game, today()) >= 30 and status != "quit"
  let oldest = sort old by next_game first 15
  for each r in oldest up to 15 {
    let m = draft sms to r.phone: "Hi {r.bowler default 'there'}, it's been a while! We'd love to see you again at the alley."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}

procedure PoolLateBalance {
  about "Remind late swimmers; escalate very late ones"
  policy PoolPolicy
  sheet SwimPasses "SwimPasses" { swimmer: Text, email: Email, expires_on: Date, status: Text, fee: Money, health_flags: Text private }
  trigger every day at 17:30

  let all = fetch SwimPasses
  let late = filter all where fee > $0.00 and days_between(expires_on, today()) > 7
  for each r in late up to 30 {
    if days_between(r.expires_on, today()) > 21 {
      notify owner "{r.swimmer} is very late ({r.fee}). Please call."
    } else {
      let m = draft email to r.email subject "A friendly reminder": "Hello {r.swimmer default 'there'}, our records show a fee of {r.fee}. Questions? Just reply."
      let ok = request approval of m from owner timeout 6 hours else skip
      send ok
    }
  }
}

procedure FurnitureRefunds {
  about "Handle refund requests within limits"
  policy FurnitureRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, client: Text, phone: Phone, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 14 {
    notify owner "Refund request {r.request_id} is older than 14 days."
    stop "outside refund window"
  }
  if r.amount > $100.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $100. Please review."
    stop "over refund limit"
  }
  if r.amount <= $20.00 {
    refund r.amount for r.request_id reason "refund request"
  } else {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 12 hours else stop "refund not approved"
  }
  update r set status = "refunded"
  let m = draft sms to r.phone: "Hi {r.client default 'there'}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 12 hours else stop "message not approved"
  send ok
}

