procedure PoolOutreachCampaign {
  about "On request, contact recent cancelled swimmers"
  policy PoolPolicy
  sheet SwimPasses "SwimPasses" { swimmer: Text, email: Email, expires_on: Date, status: Text, fee: Money, health_flags: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch SwimPasses
  let targets = filter all where status == "cancelled" and days_between(expires_on, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 100 {
    let m = draft email to r.email subject "We'd love to see you": "Hi {r.swimmer}, come back to the pool! Use code COMEBACK15 on your next visit."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
  }
}

